var jmShad;

function setup() {

  createCanvas(1112,834,WEBGL);
  rectMode(CENTER);
  noStroke();
  fill(204,100,100);
  jmShad = createShader(vert, frag);
  }

function draw() {  
  this.shader(jmShad);
  background(0);
  jmShad.setUniform('resolution',[width,height]);
  jmShad.setUniform('time',millis()/2000);
  rect(0,0,width,height);
}

let lapse = 0;    // mouse timer
function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save('pix.jpg');
    lapse = millis();
  }
}

