var frag=`

#ifdef GL_ES
precision highp float;
#endif

uniform vec2 resolution;
uniform float time;
const float PI=3.14159265359;
const float TAU = PI*2.0;
const float nb=0.01;

 vec4 quaternion(vec3 axis, float theta){
  return vec4(axis*sin(theta/2.0),cos(theta/2.0));}

vec3 qtourne(vec4 q, vec3 v){return v+2.0*cross(cross(v,q.xyz)-q.w*v,q.xyz);}

vec3 coupe(vec2 st){
 vec4 quat=quaternion(normalize(vec3(0.1*sin(time),0.4*cos(time),0.2*sin(time))),time);
  vec3  st3=vec3(-0.5+st.x,st.y,0.2*cos(time));
  st3=qtourne(quat,st3);
  vec3 col=vec3(st3.x,st3.y,1.0);//abs(sin(time*3.0))*
  st=st3.xy*nb;

  float somme=floor(pow(abs(st.y),-0.35)/(1.0+st.y*st.y))+floor(pow(abs(st.x),-0.35)/(1.0+st.x*st.x));
  if(mod(somme,2.0) > 0.0){col=vec3(abs(cos(time)),2.0*abs(sin(time)),0.0);}

  return col;
}
void main(void)
{
    vec2 ps = gl_FragCoord.xy / resolution.xy;

  ps=2.0*ps - 2.0*vec2(1.0);

    vec3 colo=coupe(ps+vec2(0.5,-0.5)); 
    gl_FragColor=vec4(colo,1.0);
}   
`;

